{"is_source_file": true, "format": "SQL", "description": "This file sets up RLS policies for 'categories' and 'expenses' tables in a Supabase project, defining who can select, insert, update, or delete their own data based on user IDs.", "external_files": [], "external_methods": ["auth.uid()"], "published": ["policies for categories", "policies for expenses"], "classes": [], "methods": [], "calls": ["alter table public.categories enable row level security", "alter table public.expenses enable row level security", "create policy \"Select own categories\" on public.categories for select using (user_id = auth.uid())", "create policy \"Insert own categories\" on public.categories for insert with check (user_id = auth.uid())", "create policy \"Update own categories\" on public.categories for update using (user_id = auth.uid())", "create policy \"Delete own categories\" on public.categories for delete using (user_id = auth.uid())", "create policy \"Select own expenses\" on public.expenses for select using (user_id = auth.uid())", "create policy \"Insert own expenses\" on public.expenses for insert with check (user_id = auth.uid())", "create policy \"Update own expenses\" on public.expenses for update using (user_id = auth.uid())", "create policy \"Delete own expenses\" on public.expenses for delete using (user_id = auth.uid())"], "search-terms": ["RLS", "supabase policies", "user-specific access", "expenses", "categories"], "state": 2, "file_id": 19, "knowledge_revision": 39, "git_revision": "", "hash": "27fefbea095d618e14c8373837b3931b", "format-version": 4, "code-base-name": "default", "filename": "expense_sync/supabase_rls_policies.sql", "revision_history": [{"39": ""}]}